mapper.update:
        UPDATE exam_user_answer
        SET grader_id=#{graderId}
		WHERE no=#{answerNo}
		  AND is_correct='W'
		  AND grader_id IS NULL
		  AND EXISTS(
			  SELECT 1
			  FROM exam_enrollment e
			  WHERE e.no=exam_user_answer.enrollment_no
			    AND (
				    e.exam_no IS NULL
				    OR EXISTS(
					    SELECT 1
					    FROM scheduled_exam se
					    WHERE se.no=e.exam_no
					      AND se.instructor_id=#{graderId}
				    )
			    )
		  )

        UPDATE exam_user_answer
        SET grader_id=NULL
        WHERE no=#{answerNo}
          AND grader_id=#{graderId}
          AND is_correct='W'
		  AND EXISTS(
			  SELECT 1
			  FROM exam_enrollment e
			  WHERE e.no=exam_user_answer.enrollment_no
			    AND (
				    e.exam_no IS NULL
				    OR EXISTS(
					    SELECT 1
					    FROM scheduled_exam se
					    WHERE se.no=e.exam_no
					      AND se.instructor_id=#{graderId}
				    )
			    )
		  )

UPDATE exam_enrollment
SET totalscore=(
        SELECT NVL(SUM(score), 0)
        FROM exam_user_answer
        WHERE enrollment_no=#{enrollmentNo}
    ),
    status='COMPLETE'
WHERE no=#{enrollmentNo}
